#include <concepts>
#include <string>
#include <type_traits>

template <class T>
concept HasStr = requires(const T& t) {
  { t.str() } -> std::convertible_to<std::string>;
};

template <class>
inline constexpr bool dependent_false = false;

template <class T>
std::string describe(const T& v) {
  if constexpr (std::is_arithmetic_v<T>) {
    return std::to_string(v);
  } else if constexpr (HasStr<T>) {
    return std::string(v.str());
  } else {
    // static_assert(false) here is ill-formed before C++23 (P2593)
    static_assert(dependent_false<T>, "describe: type needs str() or be arithmetic");
  }
}

